+      padding: 6px;
+      background: #ccc;
+      border: 1px solid #999;
+      cursor: pointer;
+    }
+    .marker {
+      position: absolute;
+      display: block;
+      width: 100%;
+      height: 2px;
+      top: 0;
+      left: 0;
+      background-color: red;
+      z-index: 0;
+      pointer-events: none;
